	@Test
	public void testMutationEntryPointsRejectAfterPrepareAcrossValidationApproaches() throws IOException {
		for (ShaclSail.TransactionSettings.ValidationApproach approach : List.of(
				ShaclSail.TransactionSettings.ValidationApproach.Auto,
				ShaclSail.TransactionSettings.ValidationApproach.Bulk,
				ShaclSail.TransactionSettings.ValidationApproach.Disabled)) {
			ShaclSail shaclSail = Utils.getInitializedShaclSail("shacl.trig");
			try {
				seedValidData(shaclSail);
				try (NotifyingSailConnection connection = shaclSail.getConnection()) {
					connection.setTransactionSettings(approach);
					connection.begin();
					assertThat(connection.hasStatement(EXISTING_SUBJECT, RDF.TYPE, RDFS.RESOURCE, false, DATA_GRAPH))
							.as("seed row exists for %s", approach)
							.isTrue();

					connection.prepare();

					UpdateContext insert = updateContext("INSERT DATA {}");
					UpdateContext delete = updateContext("DELETE DATA {}");
					assertRejected("addStatement for " + approach,
							() -> connection.addStatement(LATE_SUBJECT, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH));
					assertRejected("UpdateContext addStatement for " + approach,
							() -> connection.addStatement(insert, LATE_SUBJECT, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH));
					assertRejected("UpdateContext removeStatement for " + approach,
							() -> connection.removeStatement(delete, EXISTING_SUBJECT, RDF.TYPE, RDFS.RESOURCE,
									DATA_GRAPH));
					assertRejected("removeStatements for " + approach,
							() -> connection.removeStatements(EXISTING_SUBJECT, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH));
					assertRejected("clear for " + approach, () -> connection.clear(DATA_GRAPH));
					assertRejected("setNamespace for " + approach,
							() -> connection.setNamespace("late", "urn:late:"));
					assertRejected("removeNamespace for " + approach,
							() -> connection.removeNamespace("seed"));
					assertRejected("clearNamespaces for " + approach, connection::clearNamespaces);

					assertThat(connection.hasStatement(LATE_SUBJECT, null, null, false)).isFalse();
					assertThat(connection.hasStatement(EXISTING_SUBJECT, RDF.TYPE, RDFS.RESOURCE, false, DATA_GRAPH))
							.isTrue();
					assertThat(connection.getNamespace("seed")).isEqualTo("urn:prepare-guard:");
					assertThat(connection.getNamespace("late")).isNull();
					connection.rollback();

					connection.begin();
					connection.addStatement(FOLLOW_UP_SUBJECT, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH);
					connection.addStatement(FOLLOW_UP_SUBJECT, RDFS.LABEL, FOLLOW_UP_LABEL, DATA_GRAPH);
					connection.setNamespace("follow", "urn:follow:");
					connection.prepare();
					connection.prepare();
					connection.commit();
				}

				assertThat(readGraph(shaclSail, DATA_GRAPH)).containsExactlyInAnyOrder(
						SimpleValueFactory.getInstance()
								.createStatement(EXISTING_SUBJECT, RDF.TYPE, RDFS.RESOURCE,
										DATA_GRAPH),
						SimpleValueFactory.getInstance()
								.createStatement(EXISTING_SUBJECT, RDFS.LABEL, EXISTING_LABEL,
										DATA_GRAPH),
						SimpleValueFactory.getInstance()
								.createStatement(FOLLOW_UP_SUBJECT, RDF.TYPE, RDFS.RESOURCE,
										DATA_GRAPH),
						SimpleValueFactory.getInstance()
								.createStatement(FOLLOW_UP_SUBJECT, RDFS.LABEL,
										FOLLOW_UP_LABEL, DATA_GRAPH));
				try (NotifyingSailConnection connection = shaclSail.getConnection()) {
					assertThat(connection.getNamespace("seed")).isEqualTo("urn:prepare-guard:");
					assertThat(connection.getNamespace("follow")).isEqualTo("urn:follow:");
				}
			} finally {
				shaclSail.shutDown();
			}
		}
	}

	@Test
	public void testRepositoryUpdateIsRejectedAfterPrepare() throws IOException {
		SailRepository repository = Utils.getInitializedShaclRepository("shacl.trig");
		IRI late = Values.iri("urn:prepare-guard:sparql-late");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE, ShaclSail.TransactionSettings.ValidationApproach.Disabled);
			connection.add(EXISTING_SUBJECT, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH);
			connection.add(EXISTING_SUBJECT, RDFS.LABEL, EXISTING_LABEL, DATA_GRAPH);
			connection.commit();

			connection.begin(ShaclSail.TransactionSettings.ValidationApproach.Bulk);
			connection.prepare();
			Throwable failure = catchThrowable(() -> connection.prepareUpdate(QueryLanguage.SPARQL,
					"INSERT DATA { <urn:prepare-guard:sparql-late> "
							+ "<http://www.w3.org/1999/02/22-rdf-syntax-ns#type> "
							+ "<http://www.w3.org/2000/01/rdf-schema#Resource> }")
					.execute());
			assertThat(failure).isNotNull();
			assertThat(containsThrowable(failure, IllegalStateException.class))
					.as("SPARQL Update must reach the SHACL mutation boundary")
					.isTrue();
			assertThat(connection.hasStatement(late, null, null, false)).isFalse();
			connection.rollback();
		} finally {
			repository.shutDown();
		}
	}

	@Test
	public void testFailedPrepareRejectsMutationUntilRollbackAndFreshPrepareSucceeds() throws IOException {
		ShaclSail shaclSail = Utils.getInitializedShaclSail("shacl.trig");
		IRI invalid = Values.iri("urn:prepare-guard:invalid");
		try (NotifyingSailConnection connection = shaclSail.getConnection()) {
			connection.setTransactionSettings(ShaclSail.TransactionSettings.ValidationApproach.Bulk);
			connection.begin();
			connection.addStatement(invalid, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH);
			assertThrows(ShaclSailValidationException.class, connection::prepare);

			assertRejected("mutation after failed prepare",
					() -> connection.addStatement(invalid, RDFS.LABEL, Values.literal("too late"), DATA_GRAPH));
			assertRejected("namespace change after failed prepare",
					() -> connection.setNamespace("failed", "urn:failed:"));
			connection.rollback();
			assertThat(connection.hasStatement(invalid, null, null, false)).isFalse();

			connection.begin();
			connection.addStatement(invalid, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH);
			connection.addStatement(invalid, RDFS.LABEL, Values.literal("valid after rollback"), DATA_GRAPH);
			connection.prepare();
			connection.prepare();
			connection.commit();
		}
		assertThat(readGraph(shaclSail, DATA_GRAPH)).containsExactlyInAnyOrder(
				SimpleValueFactory.getInstance().createStatement(invalid, RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH),
				SimpleValueFactory.getInstance()
						.createStatement(invalid, RDFS.LABEL,
								Values.literal("valid after rollback"), DATA_GRAPH));
		shaclSail.shutDown();
	}

