	@Test
	public void testDefaultAndCustomShapeGraphMutationsAndMixedClearRejectAfterPrepare() throws IOException {
		ShaclSail defaultSail = Utils.getInitializedShaclSail("shacl.trig");
		try {
			seedValidData(defaultSail);
			Model shapesBefore = readGraph(defaultSail, RDF4J.SHACL_SHAPE_GRAPH);
			Model dataBefore = readGraph(defaultSail, DATA_GRAPH);
			try (NotifyingSailConnection connection = defaultSail.getConnection()) {
				connection.setTransactionSettings(ShaclSail.TransactionSettings.ValidationApproach.Bulk);
				connection.begin();
				connection.prepare();
				assertRejected("default SHACL graph add", () -> connection.addStatement(Values.iri("urn:late-shape"),
						RDF.TYPE, SHACL.NODE_SHAPE, RDF4J.SHACL_SHAPE_GRAPH));
				assertRejected("default SHACL graph removal", () -> connection.removeStatements(
						Values.iri("http://example.com/ns#PersonShape"), RDF.TYPE, SHACL.NODE_SHAPE,
						RDF4J.SHACL_SHAPE_GRAPH));
				assertRejected("mixed data and default SHACL graph clear",
						() -> connection.clear(RDF4J.SHACL_SHAPE_GRAPH, DATA_GRAPH));
				connection.rollback();
			}
			assertThat(readGraph(defaultSail, RDF4J.SHACL_SHAPE_GRAPH)).isEqualTo(shapesBefore);
			assertThat(readGraph(defaultSail, DATA_GRAPH)).isEqualTo(dataBefore);
		} finally {
			defaultSail.shutDown();
		}

		IRI customGraph = Values.iri("urn:prepare-guard:custom-shapes");
		ShaclSail customSail = new ShaclSail(new MemoryStore());
		customSail.setShapesGraphs(Set.of(customGraph));
		customSail.init();
		IRI customShape = Values.iri("urn:prepare-guard:custom-shape");
		try {
			try (NotifyingSailConnection connection = customSail.getConnection()) {
				connection.setTransactionSettings(ShaclSail.TransactionSettings.ValidationApproach.Disabled);
				connection.begin(IsolationLevels.NONE);
				connection.addStatement(customShape, RDF.TYPE, SHACL.NODE_SHAPE, customGraph);
				connection.addStatement(customShape, SHACL.TARGET_NODE, Values.iri("urn:prepare-guard:target"),
						customGraph);
				connection.commit();
			}
			seedValidData(customSail);
			Model shapesBefore = readGraph(customSail, customGraph);
			Model dataBefore = readGraph(customSail, DATA_GRAPH);
			try (NotifyingSailConnection connection = customSail.getConnection()) {
				connection.setTransactionSettings(ShaclSail.TransactionSettings.ValidationApproach.Bulk);
				connection.begin();
				connection.prepare();
				assertRejected("custom SHACL graph add",
						() -> connection.addStatement(Values.iri("urn:late-custom-shape"),
								RDF.TYPE, SHACL.NODE_SHAPE, customGraph));
				assertRejected("mixed data and custom SHACL graph clear",
						() -> connection.clear(customGraph, DATA_GRAPH));
				connection.rollback();
			}
			assertThat(readGraph(customSail, customGraph)).isEqualTo(shapesBefore);
			assertThat(readGraph(customSail, DATA_GRAPH)).isEqualTo(dataBefore);
		} finally {
			customSail.shutDown();
		}
	}

	@Test
	public void testPreparedMutationGuardDoesNotPersistLateWritesOnNativeOrLmdb(@TempDir Path tempDir)
			throws IOException {
		List<Supplier<NotifyingSail>> backends = List.of(
				() -> new NativeStore(tempDir.resolve("native").toFile()),
				() -> new LmdbStore(tempDir.resolve("lmdb").toFile()));

		for (Supplier<NotifyingSail> backend : backends) {
			ShaclSail shaclSail = (ShaclSail) Utils.getInitializedShaclSail(backend.get(), "shacl.trig");
			Model shapesBefore;
			Model dataBefore;
			try {
				seedValidData(shaclSail);
				try (NotifyingSailConnection connection = shaclSail.getConnection()) {
					connection.setTransactionSettings(ShaclSail.TransactionSettings.ValidationApproach.Bulk);
					connection.begin();
					connection.prepare();
					assertRejected("persistent backend late add", () -> connection.addStatement(LATE_SUBJECT,
							RDF.TYPE, RDFS.RESOURCE, DATA_GRAPH));
					connection.rollback();
				}
				shapesBefore = readGraph(shaclSail, RDF4J.SHACL_SHAPE_GRAPH);
				dataBefore = readGraph(shaclSail, DATA_GRAPH);
			} finally {
				shaclSail.shutDown();
			}

			ShaclSail reopened = new ShaclSail(backend.get());
			try {
				reopened.init();
				assertThat(readGraph(reopened, RDF4J.SHACL_SHAPE_GRAPH)).isEqualTo(shapesBefore);
				assertThat(readGraph(reopened, DATA_GRAPH)).isEqualTo(dataBefore);
				assertThat(readGraph(reopened, DATA_GRAPH)).doesNotContain(
						SimpleValueFactory.getInstance()
								.createStatement(LATE_SUBJECT, RDF.TYPE, RDFS.RESOURCE,
										DATA_GRAPH));
			} finally {
				reopened.shutDown();
			}
		}
	}

	@Test
	public void testPrepareFollowedByRollback() throws IOException {
		ShaclSail shaclSail = Utils.getInitializedShaclSail("shaclMinCountZero.trig");
		NotifyingSailConnection conn = shaclSail.getConnection();
		try {
			Model otherShaclData = Rio.parse(getClass().getResourceAsStream("/shacl.trig"), "",
					RDFFormat.TRIG);
			conn.begin();
			conn.clear(RDF4J.SHACL_SHAPE_GRAPH);
			otherShaclData.forEach(st -> conn.addStatement(st.getSubject(), st.getPredicate(), st.getObject(),
					RDF4J.SHACL_SHAPE_GRAPH));
			IRI bob = SimpleValueFactory.getInstance().createIRI("http://example.org/bob");
			conn.addStatement(bob, RDF.TYPE, RDFS.RESOURCE);

			conn.prepare(); // should fail because bob has no label
			Assertions.fail("constraint violation not detected on prepare call");
		} catch (ShaclSailValidationException e) {
			conn.rollback();

			// check that original shacl data (shaclMinCountZero) has been restored
			Model restoredShapeGraph = QueryResults
					.asModel(conn.getStatements(null, null, null, true, RDF4J.SHACL_SHAPE_GRAPH));

			Set<Literal> minCountValues = Models
					.objectLiterals(restoredShapeGraph.getStatements(null, SHACL.MIN_COUNT, null));
			assertThat(minCountValues).hasSize(1).allMatch(l -> l.intValue() == 0);
		} finally {
			conn.close();
			shaclSail.shutDown();
		}
	}

